import { Link } from "react-router-dom";

function Cart({ cartItems, setCartItems }) {

  const increaseQty = (id) => {
    setCartItems(cartItems.map(item =>
      item.id === id
        ? { ...item, quantity: item.quantity + 1 }
        : item
    ));
  };

  const decreaseQty = (id) => {
    setCartItems(cartItems.map(item =>
      item.id === id && item.quantity > 1
        ? { ...item, quantity: item.quantity - 1 }
        : item
    ));
  };

  const removeItem = (id) => {
    setCartItems(cartItems.filter(item => item.id !== id));
  };

  const clearCart = () => {
    setCartItems([]);
  };

  const subtotal = cartItems.reduce(
    (total, item) => total + item.price * item.quantity,
    0
  );

  const shipping = subtotal > 0 ? 50 : 0;
  const total = subtotal + shipping;

  return (
    <div style={outerStyle}>
      <div style={cartWrapper}>

        <h2 style={{ marginBottom: "30px" }}>My Cart Items</h2>

        {cartItems.length === 0 && (
          <h3>Your cart is empty 🛒</h3>
        )}

        {cartItems.map(item => (
          <div key={item.id} style={itemRow}>

            {/* Image */}
            <img
              src={item.image}
              alt={item.title}
              style={imageStyle}
            />

            {/* Title & Price */}
            <div style={{ flex: 1 }}>
              <h4>{item.title}</h4>
              <p>₹{item.price}</p>
            </div>

            {/* Quantity */}
            <div style={qtyContainer}>
              <button onClick={() => decreaseQty(item.id)} style={qtyBtn}>−</button>
              <span style={{ margin: "0 10px" }}>{item.quantity}</span>
              <button onClick={() => increaseQty(item.id)} style={qtyBtn}>+</button>
            </div>

            {/* Subtotal */}
            <div style={{ width: "120px", textAlign: "center" }}>
              ₹{item.price * item.quantity}
            </div>

            {/* Remove */}
            <button onClick={() => removeItem(item.id)} style={removeBtn}>
              Remove
            </button>

          </div>
        ))}

        {/* Buttons */}
        {cartItems.length > 0 && (
          <>
            <div style={bottomSection}>
              <Link to="/" style={continueBtn}>
                Continue Shopping
              </Link>

              <button onClick={clearCart} style={clearBtn}>
                Clear Cart
              </button>
            </div>

            {/* Summary */}
            <div style={summaryBox}>
              <p>Subtotal: ₹{subtotal}</p>
              <p>Shipping Fee: ₹{shipping}</p>
              <hr />
              <h3>Total: ₹{total}</h3>
            </div>
          </>
        )}

      </div>
    </div>
  );
}

//////////////////////////////////////////////////////////////
// Styles
//////////////////////////////////////////////////////////////

const outerStyle = {
  minHeight: "100vh",
  backgroundColor: "#f5f5f5",
  display: "flex",
  justifyContent: "center",
  paddingTop: "50px"
};

const cartWrapper = {
  width: "85%",
  maxWidth: "1200px",
  backgroundColor: "white",
  padding: "40px",
  borderRadius: "10px",
  boxShadow: "0 5px 20px rgba(0,0,0,0.1)"
};

const itemRow = {
  display: "flex",
  alignItems: "center",
  padding: "25px 0",
  borderBottom: "1px solid #ddd"
};

const imageStyle = {
  width: "130px",
  height: "90px",
  objectFit: "cover",
  marginRight: "25px",
  borderRadius: "6px"
};

const qtyContainer = {
  display: "flex",
  alignItems: "center",
  marginRight: "30px"
};

const qtyBtn = {
  padding: "6px 12px",
  fontSize: "16px",
  cursor: "pointer"
};

const removeBtn = {
  backgroundColor: "red",
  color: "white",
  border: "none",
  padding: "8px 12px",
  cursor: "pointer",
  borderRadius: "5px"
};

const bottomSection = {
  display: "flex",
  justifyContent: "space-between",
  marginTop: "30px"
};

const continueBtn = {
  backgroundColor: "#6c63ff",
  color: "white",
  padding: "10px 20px",
  textDecoration: "none",
  borderRadius: "6px"
};

const clearBtn = {
  backgroundColor: "red",
  color: "white",
  padding: "10px 20px",
  border: "none",
  borderRadius: "6px",
  cursor: "pointer"
};

const summaryBox = {
  marginTop: "30px",
  padding: "20px",
  backgroundColor: "#f0f0f0",
  borderRadius: "8px",
  width: "300px"
};

export default Cart;
